macro_rules! deps {
    () => {
        EdgeIndex!();
        Directed!();
        NodeIndex!();
        Edge!();
        Node!();
        DefaultIx!();
        Dfs!();
    };
}

macro_rules! Graph {
    () => {
        deps!();
        # [doc = " `Graph<N, E, Ty, Ix>` is a graph datastructure using an adjacency list representation."] # [doc = ""] # [doc = " `Graph` is parameterized over:"] # [doc = ""] # [doc = " - Associated data `N` for nodes and `E` for edges, called *weights*."] # [doc = "   The associated data can be of arbitrary type."] # [doc = " - Edge type `Ty` that determines whether the graph edges are directed or undirected."] # [doc = " - Index type `Ix`, which determines the maximum size of the graph."] # [doc = ""] # [doc = " The `Graph` is a regular Rust collection and is `Send` and `Sync` (as long"] # [doc = " as associated data `N` and `E` are)."] # [doc = ""] # [doc = " The graph uses **O(|V| + |E|)** space where V is the set of nodes and E is the number"] # [doc = " of edges, and allows fast node and edge insert,"] # [doc = " efficient graph search and graph algorithms."] # [doc = " It implements **O(e')** edge lookup and edge and node removals, where **e'**"] # [doc = " is some local measure of edge count."] # [doc = " Based on the graph datastructure used in rustc."] # [doc = ""] # [doc = " Here's an example of building a graph with directed edges, and below"] # [doc = " an illustration of how it could be rendered with graphviz (see"] # [doc = " [`Dot`](../dot/struct.Dot.html)):"] # [doc = ""] # [doc = " ```"] # [doc = " use petgraph::Graph;"] # [doc = ""] # [doc = " let mut deps = Graph::<&str, &str>::new();"] # [doc = " let pg = deps.add_node(\"petgraph\");"] # [doc = " let fb = deps.add_node(\"fixedbitset\");"] # [doc = " let qc = deps.add_node(\"quickcheck\");"] # [doc = " let rand = deps.add_node(\"rand\");"] # [doc = " let libc = deps.add_node(\"libc\");"] # [doc = " deps.extend_with_edges(&["] # [doc = "     (pg, fb), (pg, qc),"] # [doc = "     (qc, rand), (rand, libc), (qc, libc),"] # [doc = " ]);"] # [doc = " ```"] # [doc = ""] # [doc = " ![graph-example](https://bluss.github.io/ndarray/images/graph-example.svg)"] # [doc = ""] # [doc = " ### Graph Indices"] # [doc = ""] # [doc = " The graph maintains indices for nodes and edges, and node and edge"] # [doc = " weights may be accessed mutably. Indices range in a compact interval, for"] # [doc = " example for *n* nodes indices are 0 to *n* - 1 inclusive."] # [doc = ""] # [doc = " `NodeIndex` and `EdgeIndex` are types that act as references to nodes and edges,"] # [doc = " but these are only stable across certain operations:"] # [doc = ""] # [doc = " * **Removing nodes or edges may shift other indices.** Removing a node will"] # [doc = "   force the last node to shift its index to take its place. Similarly,"] # [doc = "   removing an edge shifts the index of the last edge."] # [doc = " * Adding nodes or edges keeps indices stable."] # [doc = ""] # [doc = " The `Ix` parameter is `u32` by default. The goal is that you can ignore this parameter"] # [doc = " completely unless you need a very big graph -- then you can use `usize`."] # [doc = ""] # [doc = " * The fact that the node and edge indices in the graph each are numbered in compact"] # [doc = "   intervals (from 0 to *n* - 1 for *n* nodes) simplifies some graph algorithms."] # [doc = ""] # [doc = " * You can select graph index integer type after the size of the graph. A smaller"] # [doc = "   size may have better performance."] # [doc = ""] # [doc = " * Using indices allows mutation while traversing the graph, see `Dfs`,"] # [doc = "   and `.neighbors(a).detach()`."] # [doc = ""] # [doc = " * You can create several graphs using the equal node indices but with"] # [doc = "   differing weights or differing edges."] # [doc = ""] # [doc = " * Indices don't allow as much compile time checking as references."] # [doc = ""] pub struct Graph < N , E , Ty = Directed , Ix = DefaultIx > { nodes : Vec < Node < N , Ix > > , edges : Vec < Edge < E , Ix > > , ty : PhantomData < Ty > , }
    };
}

Graph!();